import axios from 'axios';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

const api = axios.create({
  baseURL: API_BASE,
  headers: { 'Content-Type': 'application/json' },
});

// ── INTERCEPTORS ──────────────────────────────────────────────────────────────

// Attach JWT token to every request
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('access_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Auto-refresh token on 401
api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const original = error.config;
    if (error.response?.status === 401 && !original._retry) {
      original._retry = true;
      const refresh = localStorage.getItem('refresh_token');
      if (refresh) {
        try {
          const res = await axios.post(`${API_BASE}/auth/token/refresh/`, { refresh });
          localStorage.setItem('access_token', res.data.access);
          original.headers.Authorization = `Bearer ${res.data.access}`;
          return api(original);
        } catch (err) {
          localStorage.removeItem('access_token');
          localStorage.removeItem('refresh_token');
          window.location.href = '/login';
        }
      }
    }
    return Promise.reject(error);
  }
);

// ── AUTH API ──────────────────────────────────────────────────────────────────
export const authAPI = {
  register:       (data) => api.post('/auth/register/', data),
  verifyOTP:      (data) => api.post('/auth/verify-otp/', data),
  resendOTP:      (data) => api.post('/auth/resend-otp/', data),
  login:          (data) => api.post('/auth/login/', data),
  forgotPassword: (data) => api.post('/auth/forgot-password/', data),
  resetPassword:  (data) => api.post('/auth/reset-password/', data),
  googleAuth:     (data) => api.post('/auth/google/', data),
  getProfile:     ()     => api.get('/auth/profile/'),
  updateProfile:  (data) => api.put('/auth/profile/update/', data),
};

// ── TEAM API (Management) ─────────────────────────────────────────────────────
export const teamAPI = {
  list:       ()         => api.get('/auth/team/'),
  invite:     (data)     => api.post('/auth/invite/', data),
  update:     (id, data) => api.patch(`/auth/team/${id}/`, data),
  deactivate: (id)       => api.delete(`/auth/team/${id}/delete/`),
};

// ── PROJECTS API ──────────────────────────────────────────────────────────────
export const projectsAPI = {
  list:   ()         => api.get('/projects/'),
  create: (data)     => api.post('/projects/', data),
  get:    (id)       => api.get(`/projects/${id}/`),
  update: (id, data) => api.put(`/projects/${id}/`, data),
  delete: (id)       => api.delete(`/projects/${id}/`),

  // Dashboard & Analytics
  getDashboardStats: () => api.get('/projects/dashboard/'),
  getBudgetStats:    (id) => api.get(`/projects/${id}/budget-stats/`),

  // Members Management
  getMembers:    (id)         => api.get(`/projects/${id}/members/`),
  addMember:     (id, data)   => api.post(`/projects/${id}/members/`, data),
  removeMember:  (id, userId) => api.delete(`/projects/${id}/members/${userId}/`),

  // Tasks (Gantt / Planning)
  getTasks:    (projectId)               => api.get(`/projects/${projectId}/tasks/`),
  createTask:  (projectId, data)         => api.post(`/projects/${projectId}/tasks/`, data),
  updateTask:  (projectId, taskId, data) => api.patch(`/projects/${projectId}/tasks/${taskId}/`, data),
  deleteTask:  (projectId, taskId)       => api.delete(`/projects/${projectId}/tasks/${taskId}/`),

  // Purchases (Registre des achats)
  getPurchases:   (projectId)                   => api.get(`/projects/${projectId}/purchases/`),
  createPurchase: (projectId, data)             => api.post(`/projects/${projectId}/purchases/`, data),
  updatePurchase: (projectId, purchaseId, data) => api.patch(`/projects/${projectId}/purchases/${purchaseId}/`, data),
  deletePurchase: (projectId, purchaseId)       => api.delete(`/projects/${projectId}/purchases/${purchaseId}/`),

  // Daily Reports
  listReports:    (projectId)                  => api.get(`/projects/${projectId}/reports/`),
  createReport:   (projectId, data)            => api.post(`/projects/${projectId}/reports/`, data),
  getReport:      (projectId, reportId)        => api.get(`/projects/${projectId}/reports/${reportId}/`),
  updateReport:   (projectId, reportId, data)  => api.put(`/projects/${projectId}/reports/${reportId}/`, data),
  deleteReport:   (projectId, reportId)        => api.delete(`/projects/${projectId}/reports/${reportId}/`),
  validateReport: (projectId, reportId)        => api.post(`/projects/${projectId}/reports/${reportId}/validate/`),

  // Report Images
  uploadReportImage: (projectId, reportId, formData) =>
    api.post(`/projects/${projectId}/reports/${reportId}/images/`, formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    }),
  deleteReportImage: (projectId, reportId, imageId) =>
    api.delete(`/projects/${projectId}/reports/${reportId}/images/${imageId}/`),
};

// ── CONTRACTS API ─────────────────────────────────────────────────────────────
export const contractsAPI = {
  list:         (projectId) => api.get('/contracts/', { params: projectId ? { project: projectId } : {} }),
  upload:       (formData)  => api.post('/contracts/', formData, { headers: { 'Content-Type': 'multipart/form-data' } }),
  get:          (id)        => api.get(`/contracts/${id}/`),
  delete:       (id)        => api.delete(`/contracts/${id}/`),
  exportPdf:    (id)        => api.get(`/contracts/${id}/export-pdf/`, { responseType: 'blob' }),
  exportPdfUrl: (id)        => `${API_BASE}/contracts/${id}/export-pdf/`,
};

// ── BACKWARD COMPATIBILITY ALIASES ────────────────────────────────────────────
export const reportsAPI = {
  list:   projectsAPI.listReports,
  create: projectsAPI.createReport,
  get:    projectsAPI.getReport,
  update: projectsAPI.updateReport,
  delete: projectsAPI.deleteReport,
};

export default api;
